import{_ as l,a0 as o,w as d,s as r,ao as p,I as t,x as e,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"用 testdisk 恢復 Linux 上已刪除的文件 | LCTT x X-CMD","titleTemplate":false,"description":"用 testdisk 恢復 Linux 上已刪除的文件 | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 testdisk 恢復 Linux 上已刪除的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 testdisk 恢復 Linux 上已刪除的文件 | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20200930 Recovering deleted files on Linux with testdisk","title":"用 testdisk 恢復 Linux 上已刪除的文件","tag":"202010","desc":""},"relativePath":"202010/20200930 Recovering deleted files on Linux with testdisk.md","filePath":"[post].md"}'),c={name:"202010/20200930 Recovering deleted files on Linux with testdisk.md"};function h(k,s,g,u,b,f){const n=o("Link");return d(),r("div",null,[s[18]||(s[18]=p('<h1 id="用-testdisk-恢復-linux-上已刪除的文件" tabindex="-1">用 testdisk 恢復 Linux 上已刪除的文件 <a class="header-anchor" href="#用-testdisk-恢復-linux-上已刪除的文件" aria-label="Permalink to “用 testdisk 恢復 Linux 上已刪除的文件”">​</a></h1><blockquote><p>這篇文章介紹了 testdisk，這是恢復最近刪除的文件（以及用其他方式修復分區）的工具之一，非常方便。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2018/01/survival_life-preserver_risk_swimming_rescue-100747102-large.jpg" alt=""></p><p>當你在 Linux 系統上刪除一個文件時，它不一定會永遠消失，特別是當你最近才剛剛刪除了它的時候。</p><p>除非你用 <code>shred</code> 等工具把它擦掉，否則數據仍然會放在你的磁盤上 —— 而恢復已刪除文件的最佳工具之一 <code>testdisk</code> 可以幫助你拯救它。雖然 <code>testdisk</code> 具有廣泛的功能，包括恢復丟失或損壞的分區和使不能啓動磁盤可以重新啓動，但它也經常被用來恢復被誤刪的文件。</p><p>在本篇文章中，我們就來看看如何使用 <code>testdisk</code> 恢復已刪除的文件，以及該過程中的每一步是怎樣的。由於這個過程需要不少的步驟，所以當你做了幾次之後，你可能會覺得操作起來會更加得心應手。</p><h3 id="安裝-testdisk" tabindex="-1">安裝 testdisk <a class="header-anchor" href="#安裝-testdisk" aria-label="Permalink to “安裝 testdisk”">​</a></h3><p>可以使用 <code>apt install testdisk</code> 或 <code>yum install testdisk</code> 等命令安裝 <code>testdisk</code>。有趣的是，它不僅是一個 Linux 工具，而且還適用於 MacOS、Solaris 和 Windows。</p>',8)),t("p",null,[s[1]||(s[1]=e("文檔可在 ",-1)),a(n,{href:"https://www.cgsecurity.org/testdisk.pdf"},{default:i(()=>[...s[0]||(s[0]=[e("cgsecurity.org",-1)])]),_:1}),s[2]||(s[2]=e(" 中找到。",-1))]),s[19]||(s[19]=p(`<h3 id="恢復文件" tabindex="-1">恢復文件 <a class="header-anchor" href="#恢復文件" aria-label="Permalink to “恢復文件”">​</a></h3><p>首先，你必須以 <code>root</code> 身份登錄，或者有 <code>sudo</code> 權限才能使用 <code>testdisk</code>。如果你沒有 <code>sudo</code> 訪問權限，你會在這個過程一開始就被踢出，而如果你選擇創建了一個日誌文件的話，最終會有這樣的消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TestDisk exited normally.</span></span>
<span class="line"><span>jdoe is not in the sudoers file.  This incident will be reported.</span></span></code></pre></div><p>當你用 <code>testdisk</code> 恢復被刪除的文件時，你最終會將恢復的文件放在你啓動該工具的目錄下，而這些文件會屬於 <code>root</code>。出於這個原因，我喜歡在 <code>/home/recovery</code> 這樣的目錄下啓動。一旦文件被成功地還原和驗證，就可以將它們移回它們的所屬位置，並將它們的所有權也恢復。</p><p>在你可以寫入的選定目錄下開始：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd /home/recovery</span></span>
<span class="line"><span>$ testdisk</span></span></code></pre></div><p><code>testdisk</code> 提供的第一頁信息描述了該工具並顯示了一些選項。至少在剛開始，創建個日誌文件是個好主意，因為它提供的信息可能會被證明是有用的。下面是如何做的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Use arrow keys to select, then press Enter key:</span></span>
<span class="line"><span>&gt;[ Create ] Create a new log file</span></span>
<span class="line"><span> [ Append ] Append information to log file</span></span>
<span class="line"><span> [ No Log ] Don’t record anything</span></span></code></pre></div><p>左邊的 <code>&gt;</code> 以及你看到的反轉的字體和背景顏色指出了你按下回車鍵後將使用的選項。在這個例子中，我們選擇了創建日誌文件。</p><p>然後會提示你輸入密碼（除非你最近使用過 <code>sudo</code>）。</p><p>下一步是選擇被刪除文件所存儲的磁盤分區（如果沒有高亮顯示的話）。根據需要使用上下箭頭移動到它。然後點兩次右箭頭，當 “Proceed” 高亮顯示時按回車鍵。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Select a media (use Arrow keys, then press Enter):</span></span>
<span class="line"><span> Disk /dev/sda - 120 GB / 111 GiB - SSD2SC120G1CS1754D117-551</span></span>
<span class="line"><span>&gt;Disk /dev/sdb - 500 GB / 465 GiB - SAMSUNG HE502HJ</span></span>
<span class="line"><span> Disk /dev/loop0 - 13 MB / 13 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop1 - 101 MB / 96 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop10 - 148 MB / 141 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop11 - 36 MB / 35 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop12 - 52 MB / 49 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop13 - 78 MB / 75 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop14 - 173 MB / 165 MiB (RO)</span></span>
<span class="line"><span> Disk /dev/loop15 - 169 MB / 161 MiB (RO)</span></span>
<span class="line"><span>&gt;[Previous]  [  Next  ]  [Proceed ]  [  Quit  ]</span></span></code></pre></div><p>在這個例子中，被刪除的文件在 <code>/dev/sdb</code> 的主目錄下。</p><p>此時，<code>testdisk</code> 應該已經選擇了合適的分區類型。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Disk /dev/sdb - 500 GB / 465 GiB - SAMSUNG HE502HJ</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please select the partition table type, press Enter when done.</span></span>
<span class="line"><span> [Intel  ] Intel/PC partition</span></span>
<span class="line"><span>&gt;[EFI GPT] EFI GPT partition map (Mac i386, some x86_64...)</span></span>
<span class="line"><span> [Humax  ] Humax partition table</span></span>
<span class="line"><span> [Mac    ] Apple partition map (legacy)</span></span>
<span class="line"><span> [None   ] Non partitioned media</span></span>
<span class="line"><span> [Sun    ] Sun Solaris partition</span></span>
<span class="line"><span> [XBox   ] XBox partition</span></span>
<span class="line"><span> [Return ] Return to disk selection</span></span></code></pre></div><p>在下一步中，按向下箭頭指向 “[ Advanced ] Filesystem Utils”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[ Analyse  ] Analyse current partition structure and search for lost partitions</span></span>
<span class="line"><span>&gt;[ Advanced ] Filesystem Utils</span></span>
<span class="line"><span> [ Geometry ] Change disk geometry</span></span>
<span class="line"><span> [ Options  ] Modify options</span></span>
<span class="line"><span> [ Quit     ] Return to disk selection</span></span></code></pre></div><p>接下來，查看選定的分區。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Partition                  Start        End    Size in sectors</span></span>
<span class="line"><span>&gt; 1 P Linux filesys. data         2048  910155775  910153728 [drive2]</span></span></code></pre></div><p>然後按右箭頭選擇底部的 “[ List ]”，按回車鍵。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[  Type  ]  [Superblock] &gt;[  List  ]  [Image Creation]  [  Quit  ]</span></span></code></pre></div><p>請注意，它看起來就像我們從根目錄 <code>/</code> 開始，但實際上這是我們正在工作的文件系統的基點。在這個例子中，就是 <code>/home</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Directory /   &lt;== 開始點</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt;drwxr-xr-x     0     0      4096 23-Sep-2020 17:46 .</span></span>
<span class="line"><span> drwxr-xr-x     0     0      4096 23-Sep-2020 17:46 ..</span></span>
<span class="line"><span> drwx———     0     0     16384 22-Sep-2020 11:30 lost+found</span></span>
<span class="line"><span> drwxr-xr-x  1008  1008      4096  9-Jul-2019 14:10 dorothy</span></span>
<span class="line"><span> drwxr-xr-x  1001  1001      4096 22-Sep-2020 12:12 nemo</span></span>
<span class="line"><span> drwxr-xr-x  1005  1005      4096 19-Jan-2020 11:49 eel</span></span>
<span class="line"><span> drwxrwxrwx     0     0      4096 25-Sep-2020 08:08 recovery</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>接下來，我們按箭頭指向具體的主目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxr-xr-x  1016  1016      4096 17-Feb-2020 16:40 gino</span></span>
<span class="line"><span>&gt;drwxr-xr-x  1000  1000     20480 25-Sep-2020 08:00 shs</span></span></code></pre></div><p>按回車鍵移動到該目錄，然後根據需要向下箭頭移動到子目錄。注意，如果選錯了，可以選擇列表頂部附近的 <code>..</code> 返回。</p><p>如果找不到文件，可以按 <code>/</code>（就像在 <code>vi</code> 中開始搜索時一樣），提示你輸入文件名或其中的一部分。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Directory /shs     &lt;== current location</span></span>
<span class="line"><span>                                                   Previous</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span> -rw-rw-r—  1000  1000       426  8-Apr-2019 19:09 2-min-topics</span></span>
<span class="line"><span>&gt;-rw-rw-r—  1000  1000     24667  8-Feb-2019 08:57 Up_on_the_Roof.pdf</span></span></code></pre></div><p>一旦你找到需要恢復的文件，按 <code>c</code> 選擇它。</p><p>注意：你會在屏幕底部看到有用的説明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Use Left arrow to go back, Right to change directory, h to hide deleted files</span></span>
<span class="line"><span>    q to quit, : to select the current file, a to select all files</span></span>
<span class="line"><span>    C to copy the selected files, c to copy the current file &lt;==</span></span></code></pre></div><p>這時，你就可以在起始目錄內選擇恢復該文件的位置了（參見前面的説明，在將文件移回原點之前，先在一個合適的地方進行檢查）。在這種情況下，<code>/home/recovery</code> 目錄沒有子目錄，所以這就是我們的恢復點。</p><p>注意：你會在屏幕底部看到有用的説明：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please select a destination where /shs/Up_on_the_Roof.pdf will be copied.</span></span>
<span class="line"><span>Keys: Arrow keys to select another directory</span></span>
<span class="line"><span>      C when the destination is correct</span></span>
<span class="line"><span>      Q to quit</span></span>
<span class="line"><span>Directory /home/recovery    &lt;== 恢復位置</span></span></code></pre></div><p>一旦你看到 “Copy done! 1 ok, 0 failed” 的綠色字樣，你就會知道文件已經恢復了。</p><p>在這種情況下，文件被留在 <code>/home/recovery/shs</code> 下（起始目錄，附加所選目錄）。</p><p>在將文件移回原來的位置之前，你可能應該先驗證恢復的文件看起來是否正確。確保你也恢復了原來的所有者和組，因為此時文件由 root 擁有。</p><p><strong>注意：</strong> 對於文件恢復過程中的很多步驟，你可以使用退出（按 <code>q</code> 或“[ Quit ]”）來返回上一步。如果你願意，可以選擇退出選項一直回到該過程中的第一步，也可以選擇按下 <code>^c</code> 立即退出。</p><h4 id="恢復訓練" tabindex="-1">恢復訓練 <a class="header-anchor" href="#恢復訓練" aria-label="Permalink to “恢復訓練”">​</a></h4><p>使用 <code>testdisk</code> 恢復文件相對來説沒有痛苦，但有些複雜。在恐慌時間到來之前，最好先練習一下恢復文件，讓自己有機會熟悉這個過程。</p><hr>`,41)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),a(n,{href:"https://www.networkworld.com/article/3575524/recovering-deleted-files-on-linux-with-testdisk.html"},{default:i(()=>[...s[3]||(s[3]=[e("https://www.networkworld.com/article/3575524/recovering-deleted-files-on-linux-with-testdisk.html",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),a(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[5]||(s[5]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const v=l(c,[["render",h]]);export{m as __pageData,v as default};
